const items = $input.all();
const now = new Date();
const cutoff = new Date(now - 24 * 60 * 60 * 1000);

return items
  .map(item => {
    const p = item.json;
    const lastUpdate = p.last_manual_update ? new Date(p.last_manual_update) : null;
    if (lastUpdate && lastUpdate > cutoff) return null;
    const sales = parseFloat(p.avg_daily_sales) || 0;
    const stock = parseInt(p.current_stock) || 0;
    const new_stock = Math.max(0, stock - sales);
    return {
      json: {
        product_id: p.product_id,
        product_name: p.product_name,
        current_stock: Math.round(new_stock),
        quantity_change: -Math.min(sales, stock)
      }
    };
  })
  .filter(Boolean);

// Prepare Stock Transaction records from simulated stock changes
const items = $input.all();
const now = new Date().toISOString();

return items.map(item => {
  const p = item.json;
  // Only log if there was actually a change
  if (p.quantity_change === 0) return null;
  return {
    json: {
      product_id: p.product_id,
      product_name: p.product_name,
      transaction_type: 'sale',
      quantity_change: Math.round(p.quantity_change),
      new_stock_level: p.current_stock,
      notes: 'Daily pipeline simulated sales deduction'
    }
  };
}).filter(Boolean);

// Compute Daily Snapshot after entire pipeline completes
// We need to fetch fresh product data and alert/suggestion counts
// Since we're at the end of the pipeline, we reference earlier nodes

const products = $('Fetch Products').all().map(i => i.json);
const total = products.length;

// Count by risk level (these were updated by WF-04 in the pipeline)
// But since executeWorkflow doesn't return updated products, use what we have
// and apply the stock changes from Simulate Stock
const simulated = $('Simulate Stock').all().map(i => i.json);

let oos = 0, high = 0, medium = 0, low = 0;

// Use the simulated stock to estimate risk
simulated.forEach(s => {
  if (s.current_stock === 0) oos++;
  // Approximate risk from the original products data
  const orig = products.find(p => p.product_id === s.product_id);
  if (orig) {
    const risk = orig.risk_level || 'UNKNOWN';
    if (risk === 'HIGH') high++;
    else if (risk === 'MEDIUM') medium++;
    else if (risk === 'LOW') low++;
  }
});

// Health score formula
const score = total > 0 ? Math.round(((low * 100) + (medium * 70) + (high * 30) + (oos * 5)) / total) : 50;
const health = Math.min(100, Math.max(0, score));

const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    snapshot_date: today,
    health_score: health,
    total_products: total,
    oos_count: oos,
    high_count: high,
    medium_count: medium,
    low_count: low,
    alerts_active: 0,
    suggestions_pending: 0
  }
}];

// Log the pipeline run to System Logs
const products = $('Fetch Products').all().length;
const now = new Date().toISOString();

return [{
  json: {
    workflow_name: 'WF-08 Daily Orchestrator',
    status: 'success',
    records_processed: products,
    ran_at: now
  }
}];

